# core.py —— 零依赖内存表 + 倒排索引（原理可见）

class Table:
    def __init__(self, name, fields):
        if not fields: raise ValueError("未定义字段")
        self.name = name; self.fields = list(fields)
        self.rows = []; self.indexes = {}

    def create_index(self, col):
        inv = {}
        for i, r in enumerate(self.rows):
            inv.setdefault(r[col], set()).add(i)
        self.indexes[col] = inv

    def where(self, **kw):
        if len(kw) == 1:
            col, val = next(iter(kw.items()))
            if col in self.indexes:
                return [self.rows[i] for i in
                        sorted(self.indexes[col].get(val, set()))]
        return [r for r in self.rows
                if all(r.get(k) == v for k, v in kw.items())]

def test_index_query(tbl):
    assert len(tbl.where(device_id="DEV-02")) == 3
def test_no_index(tbl):
    assert tbl.explain(temp=3.0) == "FULL SCAN"

